static u32 syscall64_try_noarg(u64 number, u64 *result)
{
    if (number >= (sizeof(g_syscall64_noarg_kind) / sizeof(g_syscall64_noarg_kind[0])))
    {
        return 0u;
    }

    switch (g_syscall64_noarg_kind[number])
    {
        case SYSCALL64_NOARG_U16:
            *result = (u64)g_syscall64_noarg_fn[number].u16_fn();
            return 1u;

        case SYSCALL64_NOARG_U32:
            *result = (u64)g_syscall64_noarg_fn[number].u32_fn();
            return 1u;

        case SYSCALL64_NOARG_U64:
            *result = g_syscall64_noarg_fn[number].u64_fn();
            return 1u;

        default:
            return 0u;
    }
}

